from .logger import logger
from .egate_cmd_generator import EgateCmdGenerator
from taf.internal.managedobject import ManagedObject
from taf.transport.ssh import ssh
import re
csn = ssh()


class LteemuKiller(object):
    @staticmethod
    def kill_program(target, target_port, ssh_alias, sudo=False, sudo_password=None):
        """
        kill the edaemon/egate process with the given port.

        :param target: String: Target program, "edaemon" or "egate"..
        :param target_port: Int: The program port.
        :param ssh_alias: String: which connection is the target running on.
        :param sudo: Bool: whether the program run on sudo permission.
        :return: String: kill result.
        """
        get_pid_cmd = LteemuKiller._generate_get_pid_cmd(program=target,
                                                         port=target_port)
        program_pid = csn.execute(command=get_pid_cmd,
                                  connection=ssh_alias).strip()
        if program_pid == "":
            logger.info("{} --port {} doesn't exist".format(target, target_port))
            return
        kill_cmd = LteemuKiller._generate_kill_cmd(sudo=sudo,
                                                   sudo_password=sudo_password,
                                                   pid=program_pid)
        csn.execute(command=kill_cmd, connection=ssh_alias)
        csn.assert_exit_status(expected_exit_code=0, connection=ssh_alias,
                               msg="Failed to kill program, please check your arguments")

    @staticmethod
    def _generate_get_pid_cmd(**cmd_args):
        # TODO: replace it with 'fuser -k', with fallback to this one if psmisc
        # TODO: package is not installed ('fuser' command is not available).
        cmd_template = ("ps -eo pid,cmd "
                        "| grep -Ge '{program}.*--port {port}' "
                        "| grep -v 'grep'"
                        "| awk '{{print$1}}'")

        cmd = cmd_template.format(**cmd_args)
        return cmd

    @staticmethod
    def _generate_kill_cmd(sudo=False, sudo_password=None, **cmd_args):
        cmd_template = "kill -9 {pid}"
        if sudo is True or sudo == "True":
            cmd_template = "timeout 10 sudo -S " + cmd_template
            if sudo_password:
                password_temp = "echo {password} | ".format(password=sudo_password)
                cmd_template = password_temp + cmd_template
        return cmd_template.format(**cmd_args)


class LTEemulator(ManagedObject):
    """ LTEemulator
    Methods:
    - :meth:`attach`: executes the attach process
    - :meth:`detach`: executes the detach process
    """

    def __init__(self, egate_console, *args, **kwargs):
        super(LTEemulator, self).__init__(**kwargs)
        self.add_prerequisite(egate_console)
        self._egate_console = egate_console
        self.__cmd_generator = EgateCmdGenerator()

    def configure(self, file):
        """
        send cfg file command in egate console with given file name
        :param file: the name of config file.
        """
        configure_cmd = self.__cmd_generator._generate_configure_cmd(file=file)
        self._egate_console.execute(configure_cmd)

    def remove_configure(self):
        """
        reset configure in egate console, equals send "re"
        """
        self._egate_console.execute("re")

    def read_egate_output(self, filter=None):
        """
        get current outputs in egate console

        :param filter: a function to filter output
        :return:
        """
        return self._egate_console.read_output(filter=filter)

    def read_egate_output_until(self, expected, timeout=None, filter=None):
        """
        get egate output until match the expected string
        or stop when reach the timeout

        :param expected: an expected string
        :param timeout: max read time.
        :param filter: a function to filter output
        :param filter: a function to filter output
        :return: string type output in egate
        """
        return self._egate_console.read_output_until(expected,
                                                     timeout=timeout,
                                                     filter=filter)

    def read_egate_output_until_prompt(self, timeout=None, filter=None):
        ec = self._egate_console
        return ec.read_until_prompt(timeout=timeout, filter=filter)

    def read_egate_output_until_re(self, expected, timeout=None, filter=None):
        """
        get egate output until match the expected regular expression
        or stop when reach the timeout

        :param expected: an expected regular expression
        :param timeout: max read time.
        :param filter: a function to filter output
        :return: string type output in egate
        """
        return self._egate_console.read_output_until_re(expected,
                                                        timeout=timeout,
                                                        filter=filter)

    def read_lteemu_log(self, log_path, ssh_alias, expected=None, filter=None):
        """
        get contents of log file in LTEEMU.
        match expected if given, then return the content if match succeed.
        filter the result if given.

        :param log_path: full path of log file,include file name.
        :param ssh_alias: alias of connection
        :param expected: target regular expression
        :param filter: a function to filter output
        :return: content of log file
        """
        cat_cmd = self._generate_catchlog_cmd(log_path=log_path)
        log_content = csn.execute(command=cat_cmd,
                                  connection=ssh_alias)
        logger.debug("in log file:\n{}".format(log_content))
        if expected is not None:
            evaluator = re.compile(expected)
            re_result = evaluator.search(log_content)
            if re_result is None:
                raise AttributeError("can't find expected in log file")
        if filter is not None:
            log_content = filter(log_content)
        return log_content

    @staticmethod
    def _generate_catchlog_cmd(**cmd_args):
        cmd_template = "cat {log_path}"
        return cmd_template.format(**cmd_args)

    def attach(self, id,
               pdn_connectivity_type=None,
               apn=None,
               uec=None,
               get_dns=None,
               use_imsi=None,
               unknown_guti=None,
               conn_req_error=None,
               up_ciot_eps_optimisation=None,
               selected_plmn=None,
               emergency=None,
               registered_mme=None,
               dpr=None,
               ue_eutra_capabilities=None,
               ue_utra_capabilities=None,
               ue_geran_cs_capabilities=None,
               ue_geran_ps_capabilities=None,
               ue_cdma2000_1xrtt_capabilities=None,
               ue_eutra_nr_capabilities=None,
               ue_nr_capabilities=None,
               profile=None,):
        """
        Initiates UE Attach procedure.

        :param id: Int: Specified UE ID
        :param pdn_connectivity_type: String: (Optional) IP version of PDN connectivity
        :param apn: String: (Optional) Access Point Name in ESM information response
        :param uec: String: (Optional) Script filename to execute at UEC
        :param get_dns: String: (Optional) Toggle reception of DNS servers info from PGW (using PCO)
        :param use_imsi: String: (Optional) Toggle of IMSI usage (even with available GUTI)
        :param unknown_guti: String: (Optional) Toggle of sending unknown GUTI in NAS:
                                       AttachRequest (used for MME testing)
        :param conn_req_error: String: (Optional) Toggle forced error in RRCConnectionRequest
        :param up_ciot_eps_optimisation: String: (Optional) Toggle up-CIoT-EPS-Optimisation
                                                         for RRCConnectionSetupComplete-NB
        :param selected_plmn: String: (Optional) Specified PLMN ID sent in
                                   RrcConnectionSetupComplete/RrcConnectionSetupComplete-NB
        :param emergency: String: (Optional) Toggle for Emergency Attach
                                            (not applicable for NB-IoT UE)
        :param registered_mme: String: (Optional) Registered MME for
                                     RRCConnectionSetupComplete/RrcConnectionSetupComplete-NB
        :param dpr: String: (Optional) Data Pull Request (for NB-IoT UEs,
                            UL Data Volume and PHR to be used for deriving NB MSG3 DPR, format is data_volume:phr)
        :param ue_eutra_capabilities: String: (Optional) UE E-UTRA Capabilities (hex)
        :param ue_utra_capabilities: String: (Optional) UE UTRA Capabilities (hex)
        :param ue_geran_cs_capabilities: String: (Optional) UE GERAN CS Capabilities (hex)
        :param ue_geran_ps_capabilities: String: (Optional) UE GERAN PS Capabilities (hex)
        :param ue_cdma2000_1xrtt_capabilities: String: (Optional) UE CDMA2000 1xRTT Capabilities (hex)
        :param ue_eutra_nr_capabilities: String: (Optional) UE EUTRA NR Capabilities (hex)
        :param ue_nr_capabilities: String: (Optional) UE NR Capabilities (hex)
        :param profile: String: (Optional) Test profile in 5G-UE
        :return:
        """
        cmd = self.__cmd_generator._generate_attach_cmd(
            id=id,
            pdn_connectivity_type=pdn_connectivity_type,
            apn=apn,
            uec=uec,
            get_dns=get_dns,
            use_imsi=use_imsi,
            unknown_guti=unknown_guti,
            conn_req_error=conn_req_error,
            up_ciot_eps_optimisation=up_ciot_eps_optimisation,
            selected_plmn=selected_plmn,
            emergency=emergency,
            registered_mme=registered_mme,
            dpr=dpr,
            ue_eutra_capabilities=ue_eutra_capabilities,
            ue_utra_capabilities=ue_utra_capabilities,
            ue_geran_cs_capabilities=ue_geran_cs_capabilities,
            ue_geran_ps_capabilities=ue_geran_ps_capabilities,
            ue_cdma2000_1xrtt_capabilities=ue_cdma2000_1xrtt_capabilities,
            ue_eutra_nr_capabilities=ue_eutra_nr_capabilities,
            ue_nr_capabilities=ue_nr_capabilities,
            profile=profile)
        self._egate_console.execute(cmd)

    def detach(self, id):
        """
        send detach command in the egate console with given id
        :param id: a number of detach id
        """
        detach_cmd = self.__cmd_generator._generate_detach_cmd(id=id)
        self._egate_console.execute(detach_cmd)

    def bearer_inject_gtpu_error_ind(self, by, device_id, ue, bearer,
                                     with_udp_port=None, abnormal_scenario=None):
        """
        Initiates spontaneous sending of GTPU error indication concerning
        the given dual connected UE's from either eNB or SGW (user choice) to gNB.

        :param by: String: Device that will send the error indication message (eNodeB / SGW).
        :param device_id: Int: Local identifier for eNodeB / SGW.
        :param ue: Int: Specified UE ID(s)
        :param bearer: Int: Specified Bearer ID(s)
        :param with_udp_port: (Optional) String: Flag to determine if
                                            UDP port is present in extension header.
        :param abnormal_scenario: (Optional) String: Type of abnormal scenario to set
                                                   in the error indication message.
        :return:
        """
        cmd = self.__cmd_generator._generate_bearer_inject_gtpu_error_ind(
            by=by, device_id=device_id, ue=ue, bearer=bearer,
            with_udp_port=with_udp_port,
            abnormal_scenario=abnormal_scenario
        )
        self._egate_console.execute(cmd)

    def bearer_stats(self, ue, id=None, srb_id=None, dir=None, type=None,
                     scell=None, format=None, size_unit=None,
                     trf_id=None, dc_cell_group=None):
        """
        Displays bearer statistics or per-traffic(s) statistics of the bearer.

        :param ue: Int: Specified UE ID(s)
        :param id: (Optional) Int: Specified Bearer ID(s)
        :param srb_id: (Optional) Int: Signaling Radio Bearer Identifier(s)
                                       (for 'l3_srb' and 'rlc' only)
        :param dir: (Optional) String: direction
        :param type: (Optional) String: Statistics type
        :param scell: (Optional) String: Carrier Aggregation serving cell
                                         (carrier component, CC).
                                         Primary is for scell index 0.
                                         Secondary is for scell indexes 1-7.
        :param format: (Optional) String: Display Format
        :param size_unit: (Optional) String: unit of PDU/SDU/packets size
        :param trf_id: (Optional) Int: Traffic id/ids (only for internal traffic. default=all).
                                       For 'l3_trf' type
        :param dc_cell_group: (Optional) String: Displays the UE's MCG or SCG bearer statistics
                                                 (applicable only for DC bearers)
        :return:
        """
        bearer_stats_cmd = self.__cmd_generator._generate_bearer_stats(
            ue=ue, id=id, srb_id=srb_id, dir=dir, type=type, scell=scell,
            format=format, size_unit=size_unit, trf_id=trf_id, dc_cell_group=dc_cell_group
        )
        self._egate_console.execute(bearer_stats_cmd)

    def enb_ue_dc_modify(self, ue, by, cause, bearer=None, ambr=None,
                         bearer_to_add=None,
                         bearer_to_modify=None,
                         bearer_to_release=None,
                         scg_config_query=None):
        """
        Command to trigger LTE-NR dual connectivity modification

        :param ue: Int: Specified UE ID
        :param by: String: Determines the initiator of the DC procedure
        :param cause: String: Cause for the DC procedure
        :param bearer: (Optional) Int: Bearer id
        :param ambr: (Optional) Int: Update aggregate max bit rate, DL:UL
        :param bearer_to_add: (Optional) Int: To Added Bearer ID List
        :param bearer_to_modify: (Optional) Int: To Modified Bearer ID List
        :param bearer_to_release: (Optional) Int: To Released Bearer ID List
        :param scg_config_query: (Optional) String: Send X2AP SGNB MODIFICATION
                                                    REQUEST with SCG Configuration Query
        :return:
        """
        cmd = self.__cmd_generator._generate_enb_ue_dc_modify(
            ue=ue,
            by=by,
            cause=cause,
            bearer=bearer,
            ambr=ambr,
            bearer_to_add=bearer_to_add,
            bearer_to_modify=bearer_to_modify,
            bearer_to_release=bearer_to_release,
            scg_config_query=scg_config_query,
        )
        self._egate_console.execute(cmd)

