    def link_x2_reset(self, from_id, to_id, ue_id=None, timeout=None):
        """

        :param from_id: Int: Initiator device ID for sending X2_RESET message
        :param to_id: Int: Device ID receiving X2_RESET message
        :param timeout: Int: (Optional if needed)Device setting X2 reset timeout duration (ms)
                             if not given, will be default value 1000ms.
        :param ue_id: List: (Optional if needed)List of UE ID's for X2 reset message

        """
        link_x2_reset_cmd = self.__cmd_generator._generate_x2_reset(timeout=timeout,
                                                                    from_id=from_id,
                                                                    to=to_id,
                                                                    ue=ue_id)
        return self._egate_console.execute(link_x2_reset_cmd)

