    def enb_endc_param(self, id,
                       x2_gnb_retry_limit=None,
                       send_reset_response=None,
                       scg_dl_dist_percent=None,
                       dud_retx_indication=None,
                       enable_dud_poll_bit=None,
                       dud_poll_period_in_packet=None,
                       dud_poll_period_in_ms=None,
                       enable_dud_payload=None,
                       enable_dud_payload_in_polling=None,
                       force_nru_sn_jump=None,
                       enable_dl_data_forwarding=None,
                       enable_ul_data_forwarding=None,
                       use_nr_ran_cont=None,
                       inject_gtpu_error_ind_after_sgnb_release=None,
                       dl_data_shuffling=None,
                       action=None,
                       dl_flush_nr_pdpc_pdu_sn=None,
                       dl_discard_nr_pdpc_pdu_sn=None,
                       serv_cell_index=None,
                       menb_failure_scenario=None,
                       ddds_suspend=None,
                       control_flow_period=None,
                       desired_buffer_sizes=None,
                       dl_data_delivery_success_rate=None,
                       long_pdcp_pdu_number_comprehension_required=None,
                       modify_gtpu_header=None):
        """
        Updates online changeable parameters related to dual connectivity - ENB.

        :param id: Int: Local identifier for eNodeB / gNodeB
        :param x2_gnb_retry_limit: String:(Optional) allowed number of retries when establishing X2 (GNB) SCTP link
        :param send_reset_response: String:(Optional) Enabled/Disable sending of X2AP:Reset Response by GNB
        :param scg_dl_dist_percent: String:(Optional) Percentage of downlink data flow to SCG leg
        :param dud_retx_indication: String:(Optional) Forces Retransmission flag in DL User Data
        :param enable_dud_poll_bit: String:(Optional) Enable Report Polling bit in DL User Data
        :param dud_poll_period_in_packet: String:(Optional) Report Polling bit will be set every nth DUD packet
        :param dud_poll_period_in_ms: String:(Optional) DUD polling will be sent every n milliseconds
        :param enable_dud_payload: String:(Optional) Send DL User Data w/ actual payload
        :param enable_dud_payload_in_polling: String:(Optional) Send DL User Data w/ actual payload during
                                                                Polling period
        :param force_nru_sn_jump: String:(Optional) Forces skipping of certain NR-U sequences
        :param enable_dl_data_forwarding: String:(Optional) Enable DL Data forwarding to target
        :param enable_ul_data_forwarding: String:(Optional) Enable UL Data forwarding to target
        :param use_nr_ran_cont: String:(Optional) Switches container to be used in GTPU Extension header
        :param inject_gtpu_error_ind_after_sgnb_release: String:(Optional) Send GTPU Error Indication after
                                                                           sending SgNB Release Request Ack
        :param dl_data_shuffling: String:(Optional) Sets the buffering size for DL shuffling of packets
        :param action: String:(Optional) Action of message to which kind of error to produce
        :param dl_flush_nr_pdpc_pdu_sn: String:(Optional) Enable sending of DL Flush Packet
                                                          info with specified DL NR discard PDCP sequence number
        :param dl_discard_nr_pdpc_pdu_sn: String:(Optional) Enable sending DL Discard Blocks
                                          (DL discard NR PDCP PDU SN and Discarded Block Size).
                                          Format is {SN1:BlockSize1},...{SNn:BlockSizen} eg. 1:2,13:56
        :param serv_cell_index: String:(Optional) Enable sending of serving cell ID of PSCell with the specified value
        :param menb_failure_scenario: String:(Optional) MeNB failure behavior to be simulated
        :param ddds_suspend: String:(Optional) Set DDDS transmission delay
        :param control_flow_period: String:(Optional) Set DDDS flow control and period.
        :param desired_buffer_sizes: String:(Optional) Set minimum desired buffer size for
                                            UE and desired buffer size for Data Radio Bearer.
        :param dl_data_delivery_success_rate: String:(Optional) Set ratio between Highest s
                                                     uccessfully Delivered and Transmitted NR PDCP SNs
        :param long_pdcp_pdu_number_comprehension_required: String:(Optional)
                    Switches type of extension header for Long PDCP PDU Number if comprehension is required
        :param modify_gtpu_header: String:(Optional) Modifies GTPU Header to make it Invalid
        :return:
        """
        enb_endc_param_cmd = self.__cmd_generator._generate_enb_endc_param(
            id=id,
            x2_gnb_retry_limit=x2_gnb_retry_limit,
            send_reset_response=send_reset_response,
            scg_dl_dist_percent=scg_dl_dist_percent,
            dud_retx_indication=dud_retx_indication,
            enable_dud_poll_bit=enable_dud_poll_bit,
            dud_poll_period_in_packet=dud_poll_period_in_packet,
            dud_poll_period_in_ms=dud_poll_period_in_ms,
            enable_dud_payload=enable_dud_payload,
            enable_dud_payload_in_polling=enable_dud_payload_in_polling,
            force_nru_sn_jump=force_nru_sn_jump,
            enable_dl_data_forwarding=enable_dl_data_forwarding,
            enable_ul_data_forwarding=enable_ul_data_forwarding,
            use_nr_ran_cont=use_nr_ran_cont,
            inject_gtpu_error_ind_after_sgnb_release=inject_gtpu_error_ind_after_sgnb_release,
            dl_data_shuffling=dl_data_shuffling,
            action=action,
            dl_flush_nr_pdpc_pdu_sn=dl_flush_nr_pdpc_pdu_sn,
            dl_discard_nr_pdpc_pdu_sn=dl_discard_nr_pdpc_pdu_sn,
            serv_cell_index=serv_cell_index,
            menb_failure_scenario=menb_failure_scenario,
            ddds_suspend=ddds_suspend,
            control_flow_period=control_flow_period,
            desired_buffer_sizes=desired_buffer_sizes,
            dl_data_delivery_success_rate=dl_data_delivery_success_rate,
            long_pdcp_pdu_number_comprehension_required=long_pdcp_pdu_number_comprehension_required,
            modify_gtpu_header=modify_gtpu_header,
        )
        self._egate_console.execute(enb_endc_param_cmd)

